body:
{
  "pains": [
    {
      "id": "pain:check-every-cite",
      "statement": "The AI answer reads fine, but I still have to pull and read every case it cites, and if it misses something it's my name on the advice, not the vendor's.",
      "element": "b2b:individual:reduced_anxiety",
      "shape": {
        "surface": "The AI answer cites authority that turns out not to say what it claims, or tells you your view is mistaken when it is not.",
        "operational": "Every cited case gets pulled and read, its later history checked, and the AI's prose edited before anything goes into a memo, brief or client advice, which eats the time the tool was meant to save.",
        "personal": "If the software fails to flag an issue and you fail to flag it to the client, you carry that, because the software provider will not indemnify you."
      },
      "workflow": "Research and advice drafting: putting the question to an AI assistant, then pulling each cited case in Westlaw or Lexis to read it and check its subsequent history, then rewriting the answer before it goes into the brief or the client email.",
      "type": "felt",
      "confidence": "low",
      "priority": 1,
      "felt_evidence": {
        "kind": "complaining",
        "what": "A law professor complained publicly in April 2026 that Claude told him his view was mistaken, and that reading the cases showed Claude was completely wrong.",
        "cites": ["src:1"]
      },
      "triggers": [],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "I read them and the other cases and verified that Claude was completely wrong.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "If you actually look up every citation, hallucinations are incredibly easy to spot.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "If the software you use fails to flag an obvious issue that you consequently fail to flag to your client",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "the software provider won't be indemnifying you for it.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "The time spent checking the chatbot's work and editing its prose, on top of the research itself.",
          "fears": "Something the tool missed goes to the client under their name, and the vendor carries none of the liability.",
          "dream_outcome": "An answer whose citations they can trust without re-reading every case, or a tool that takes responsibility for what it misses."
        }
      },
      "relief": {
        "line": "Not yet written. No buyer has described the after-state in a source this run could read.",
        "says": [],
        "gap": "Looked for 4 and 5 star reviews on G2, Capterra and TrustRadius (all returned 403) and for 'finally solved' threads on Reddit (host blocked). No fetchable buyer page described what it feels like when citation checking stopped being a burden."
      },
      "euphoria": {
        "line": "Not yet written. No buyer source shows a standing change past relief.",
        "says": [],
        "gap": "Same blocked review sites and communities as relief; no buyer page read describes the year after."
      },
      "segments": ["seg:biglaw"],
      "feature_ref": null,
      "feature_note": "brain/company names no citation-verification feature. Agent claims to 'review' work, which may address this, but no buyer source tests that claim; a feature that links every cited proposition to the passage that supports it would kill this pain.",
      "cites": ["src:1", "src:2"]
    },
    {
      "id": "pain:data-room-all-nighters",
      "statement": "The target dumps everything into 40-50 data room folders, the DD report is due in two weeks, and it's 4am nights reading documents until it's done.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "A data room of 40-50 folders uploaded by the target with no order to it, and a DD report due in about two weeks.",
        "operational": "Associates read document after document by hand, fill the DD report against the checklist, and pull regular all-nighters to make the deadline.",
        "personal": "Weeks on a three hour sleep schedule, workdays with no end time, and staying up till 4am-5am on documents."
      },
      "workflow": "M&A and capital markets due diligence: opening the virtual data room the target company uploaded in 40-50 folders, reading each document, and writing findings into the DD report and checklist, inside a turnaround of about two weeks.",
      "type": "felt",
      "confidence": "low",
      "priority": 2,
      "felt_evidence": {
        "kind": "complaining",
        "what": "A capital markets associate at an Indian Tier-1 firm posted their working hours as '9:30 AM - no end time' because they are overworked and every day is deal sensitive.",
        "cites": ["src:5"]
      },
      "triggers": [
        {
          "event": "A signed deal that gives the team about two weeks to turn around the DD report.",
          "cites": ["src:4"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "DDs usually involve huge volumes of data, so after a while going through so many documents feels mind numbing.",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "No one likes staying up till 4am-5am in the night to work on documents under such tight deadlines.",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "the documents are simply uploaded in 40-50 folders by the target company",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "Working Hours: 9:30 AM - no end time (we are overworked and everyday is deal sensitive)",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "have spent weeks on a three hour sleep schedule.",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "No, most people dont work till 9/9:30. It’s usually alot worse.",
              "cites": ["src:6"]
            }
          ],
          "costs_them": "Nights and sleep: weeks of 4am finishes reading data room documents to hit the report deadline.",
          "fears": "No source shows the fear directly; the quotes stop at the hours and the tedium.",
          "dream_outcome": "The data room read and the DD report done inside normal hours, with the mind-numbing first pass off their desk."
        }
      },
      "relief": {
        "line": "Not yet written. No buyer has described a DD that finished at a normal hour.",
        "says": [],
        "gap": "Review sites (G2, Capterra, TrustRadius) returned 403 and Reddit was blocked, so the 4 and 5 star reviews and 'finally' threads where an associate would describe this were never read."
      },
      "euphoria": {
        "line": "Not yet written. No buyer source shows the standing change.",
        "says": [],
        "gap": "Same blocked sources as relief; nothing read describes what changes a year after DD stops meaning all-nighters."
      },
      "segments": ["seg:biglaw"],
      "feature_ref": "feat:tabular",
      "feature_note": "Tabular review puts many documents side by side in a table, which is the data-room first pass these associates describe. Both sources are Indian Tier-1 firms, not AmLaw or Global 100; see q:pains-dataroom-us-uk.",
      "cites": ["src:4", "src:5"]
    },
    {
      "id": "pain:show-the-ceo-ai-gains",
      "statement": "The CEO and board want to hear what legal is doing with AI and see the productivity gains, and meanwhile the AI strategy sits in a committee deck nobody executes.",
      "element": "b2b:individual:reputational_assurance",
      "shape": {
        "surface": "Leadership asks what the legal department is doing with AI, and the company's AI strategy lives in slide decks owned by IT and a committee.",
        "operational": "The GC has to adopt AI in the department and produce evidence of productivity gains for the C-suite, while working inside a committee structure that does not decide.",
        "personal": "Their standing with the C-suite rides on showing meaningful productivity gains from AI that nobody has given them a way to measure."
      },
      "workflow": "The GC's update to the CEO and board on AI: the legal department's adoption plan, the enterprise AI committee where IT leads and everyone weighs in, and the productivity numbers leadership asks legal to show.",
      "type": "felt",
      "confidence": "medium",
      "priority": 3,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Cox Media Group's chief legal officer wrote in August 2026 that committee-led enterprise AI strategies live in slide decks and die in execution, and argued the GC should own it.",
        "cites": ["src:8"]
      },
      "triggers": [
        {
          "event": "CEOs and boards asking general counsel to show they are using AI to find efficiencies, as reported in December 2025.",
          "cites": ["src:9"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "There is a lot of pressure from the C-Suite on legal departments to adopt AI",
              "cites": ["src:7"]
            },
            {
              "situation": "venting",
              "verbatim": "That produces strategies that live in slide decks and die in execution",
              "cites": ["src:8"]
            },
            {
              "situation": "venting",
              "verbatim": "Without clear ownership, even well-chartered committees lack the cohesion to act effectively.",
              "cites": ["src:8"]
            }
          ],
          "costs_them": "Standing with the CEO and board, which now includes showing meaningful productivity gains from AI.",
          "fears": "The department is seen as behind on AI while the strategy stays stuck in committee.",
          "dream_outcome": "Owning the AI strategy and being able to show leadership what the department gained from it."
        }
      },
      "relief": {
        "line": "Not yet written. No buyer source describes a GC who can show the gains.",
        "says": [],
        "gap": "In-house reviews on G2 and Capterra returned 403; the only GC voices read describe the pressure, not the after-state."
      },
      "euphoria": {
        "line": "Not yet written. No buyer source shows the standing change.",
        "says": [],
        "gap": "No fetchable buyer page described what changed for a GC a year after showing AI gains to the board."
      },
      "segments": ["seg:inhouse"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company reports usage or value to leadership. A dashboard of work done, hours saved and matters handled that a GC can put in front of the CEO would kill this pain.",
      "cites": ["src:7", "src:8"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "The buyers who spoke ask which AI tools actually deliver reliable output and how to use generative AI in the department, so they know solutions exist and are choosing among them, not learning that they exist.",
      "cites": ["src:10", "src:7"]
    }
  },
  "stats": [],
  "keywords": [
    "check every citation AI legal research",
    "AI hallucinated case citation lawyer",
    "due diligence data room review deadline",
    "DD report turnaround two weeks",
    "legal department AI ROI CEO board",
    "general counsel AI strategy ownership",
    "legal AI reliable output not hype"
  ],
  "questions": [
    {
      "id": "q:pains-first-call",
      "question": "On the first call, which problem did your last ten customers name before anything else: checking AI output, data room review, showing AI value to leadership, or something not on this list?",
      "why": "Every pain here is built from public voices because review sites and Reddit refused fetches; one answer from real customers outranks all of it.",
      "would_change": "pains[].priority"
    },
    {
      "id": "q:pains-dataroom-us-uk",
      "question": "Do associates at your US and UK large-firm customers describe data room DD the same way: 40-50 folders, two weeks, 4am finishes?",
      "why": "Both sources for pain:data-room-all-nighters are Indian Tier-1 firms, which fit 200+ lawyers but not the AmLaw or Global 100 filter.",
      "would_change": "pains[pain:data-room-all-nighters].confidence, pains[pain:data-room-all-nighters].segments"
    },
    {
      "id": "q:pains-cite-checking-with-legora",
      "question": "Do your users still pull and read every case Legora cites before relying on it, and does Agent's review step change that?",
      "why": "No feature in brain/company is named for citation verification, so the map left feature_ref null on the top pain.",
      "would_change": "pains[pain:check-every-cite].feature_ref"
    },
    {
      "id": "q:pains-hype-vs-reliable",
      "question": "Do small and boutique firms tell you they cannot tell which legal AI tools deliver reliable output and which are hype?",
      "why": "Found once: a small boutique firm on Legally India asked for tools that 'actually deliver a good and reliable output and not just AI hype' (src:10). One source is not a pain.",
      "would_change": "pains[]"
    },
    {
      "id": "q:pains-dont-charge-me",
      "question": "Do your law firm customers report clients refusing to pay for time AI saved, or asking for lower bills because the firm uses AI?",
      "why": "Only press carried it: a senior general counsel quoted in Bar & Bench saying 'Don't charge me for it' (src:11). No buyer-class source was readable.",
      "would_change": "pains[]"
    },
    {
      "id": "q:pains-seat-minimums",
      "question": "Have mid-size firms told you they were priced out of competitors by seat minimums or annual commitments?",
      "why": "Every page claiming seat minimums was a vendor or review blog citing Reddit secondhand; none was a buyer voice that could be read.",
      "would_change": "pains[], segments for seg:midsize-firms"
    },
    {
      "id": "q:pains-gc-proof",
      "question": "When a GC customer reports to their CEO or board on AI, what do they show, and does Legora give them anything to show it with?",
      "why": "pain:show-the-ceo-ai-gains has no feature in brain/company that addresses it.",
      "would_change": "pains[pain:show-the-ceo-ai-gains].feature_ref, pains[pain:show-the-ceo-ai-gains].shape.personal"
    },
    {
      "id": "q:pains-after-state",
      "question": "What do customers say a few months in, in their own words, about what changed?",
      "why": "Every relief and euphoria cell is a gap; the after-state sources (4 and 5 star reviews, community wins threads) were all blocked.",
      "would_change": "pains[].relief, pains[].euphoria"
    }
  ],
